message.content:
- Failures recur when the agent skips a required transform, places a raw target at the goal, or wanders past an available target/put opportunity.
- Maintain reusable stages: find_target, take_target, transform, go_destination, put_target, wrong_inventory, plus transform_done and placed_count.
- on_init teaches task order; on_post_step updates stage from inventory, action, observation, and admissible actions; make_pre_hint gives deduped subgoal guidance.
- Avoid hard forcing numbered ALFWorld actions and avoid destination puts when inventory is not the target, preserving successful trajectories.
</think>
<patch>{
  "benchmark": "alfworld",
  "description": "Add compact stage tracking and soft guidance for target transforms and missed placement opportunities.",
  "actions": [
    {
      "type": "add_code_hook",
      "hook": "on_init",
      "code": "def hook(ctx, nb):
    nb['stage'] = 'find_target'
    nb['transform_done'] = False
    nb['placed_count'] = 0
    nb['last_hint'] = ''
    return {'skills': [{'text': 'Follow ALFWorld order: find and take the target type, do any required clean heat cool or slice step, then carry it to the destination and use the put action. Do not place a raw target when a transform is required.'}], 'tool_hint': 'Prefer admissible actions that advance the current subgoal; avoid closing or leaving when a target take or destination put is available.'}"
    },
    {
      "type": "add_code_hook",
      "hook": "on_post_step",
      "code": "def text(x):
    return str(x or '').lower()

def need(task_type):
    if 'clean' in task_type:
        return 'clean'
    if 'heat' in task_type:
        return 'heat'
    if 'cool' in task_type:
        return 'cool'
    if 'slice' in task_type:
        return 'slice'
    return ''

def inv_has(inv, target):
    s = text(inv)
    return bool(target and target in s and 'not carrying' not in s and 'nothing' not in s)

def action_text(ctx):
    a = ctx.get('action') or {}
    if isinstance(a, dict):
        return text(a.get('final_action') or a.get('normalized') or a.get('raw'))
    return text(ctx.get('action.final_action') or ctx.get('action.normalized') or ctx.get('action.raw'))

def has_adm(adm, prefix, target, dest):
    for x in adm or []:
        s = text(x)
        if not s.startswith(prefix):
            continue
        if target and target not in s:
            continue
        if dest and dest not in s:
            continue
        return True
    return False

def hook(ctx, nb):
    task = ctx.get('task') or {}
    world = ctx.get('world') or {}
    target = text(task.get('target_type') or ctx.get('task.target_type'))
    dest = text(task.get('destination_type') or ctx.get('task.destination_type'))
    task_type = text(task.get('task_type') or ctx.get('task.task_type'))
    verb = need(task_type)
    if not verb:
        nb['transform_done'] = True
    else:
        act = action_text(ctx)
        obs = text(ctx.get('observation'))
        if act.startswith(verb + ' ') and target in act and 'nothing happens' not in obs and 'cannot' not in obs:
            nb['transform_done'] = True
    inv = world.get('inventory') or ctx.get('world.inventory')
    carrying_target = inv_has(inv, target)
    carrying_any = inv and text(inv) not in ('[]', '{}') and 'nothing' not in text(inv) and 'not carrying' not in text(inv)
    if carrying_any and target and not carrying_target:
        nb['stage'] = 'wrong_inventory'
    elif carrying_target:
        if verb and not nb.get('transform_done'):
            nb['stage'] = 'transform'
        else:
            nb['stage'] = 'put_target' if (has_adm(ctx.get('admissible') or [], 'put ', target, dest) or (dest and dest in text(world.get('current_location') or ctx.get('world.current_location')))) else 'go_destination'
    else:
        take_avail = has_adm(ctx.get('admissible') or [], 'take ', target, '')
        nb['stage'] = 'take_target' if take_avail else 'find_target'
        if take_avail and target and target in text(world.get('target_location') or ctx.get('world.target_location')) and not nb.get('target_taken'):
            nb['target_taken'] = True
    if target and action_text(ctx).startswith('put ') and target in action_text(ctx) and 'you put' in obs and (not dest or dest in obs):
        old = nb.get('placed_count') or 0
        try:
            nb['placed_count'] = int(old) + 1
        except Exception:
            nb['placed_count'] = 1
        if verb and not nb.get('transform_done'):
            nb['stage'] = 'transform'
    pc = world.get('placed_count')
    if pc is not None:
        try:
            nb['placed_count'] = int(pc)
        except Exception:
            pass
    return None"
    },
    {
      "type": "add_code_hook",
      "hook": "make_pre_hint",
      "code": "def need(task_type):
    if 'clean' in task_type:
        return 'clean'
    if 'heat' in task_type:
        return 'heat'
    if 'cool' in task_type:
        return 'cool'
    if 'slice' in task_type:
        return 'slice'
    return ''

def hook(ctx, nb):
    task = ctx.get('task') or {}
    target = text(task.get('target_type') or ctx.get('task.target_type'))
    dest = text(task.get('destination_type') or ctx.get('task.destination_type'))
    task_type = text(task.get('task_type') or ctx.get('task.task_type'))
    verb = need(task_type)
    stage = nb.get('stage') or 'find_target'
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory appears to hold a non-target item; do not place it at the goal. Recover by setting it down if needed, then find the target type.'
    elif stage == 'transform' and target and verb and not nb.get('transform_done'):
        msg = 'This target still needs the required ' + verb + ' step before any destination put. Go to the proper appliance and use the admissible ' + verb + ' action.'
    elif stage == 'take_target' and target:
        msg = 'A target ' + target + ' is available here; take an admissible take action for it instead of closing containers or leaving.'
    elif stage == 'put_target' and target and dest and verb and not nb.get('transform_done'):
        msg = 'Do not put the ' + target + ' at the ' + dest + ' yet; first complete the required ' + verb + ' transform.'
    elif stage == 'put_target' and target and (not verb or nb.get('transform_done')):
        msg = 'You are carrying the target; go to the ' + dest + ' and use the admissible put action there.'
    elif stage == 'go_destination' and target and dest and (ctx.get('predicates.same_observation_repeated') or ctx.get('predicates.same_action_repeated') or ctx.get('predicates.remaining_steps_low')):
        msg = 'Keep carrying the ' + target + ' and navigate to the ' + dest + ' for the final put.'
    if not msg:
        return None
    key = stage + ':' + msg[:70]
    if not key or nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}"
    }
  ]
}</patch>
